import{_ as a,o as t,c as r,ag as n}from"./chunks/framework.ePeAWSvT.js";const c=JSON.parse('{"title":"RoadMap","description":"","frontmatter":{},"headers":[],"relativePath":"guide/roadmap.md","filePath":"guide/roadmap.md"}'),o={name:"guide/roadmap.md"};function l(s,e,i,d,h,g){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="roadmap" tabindex="-1">RoadMap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;RoadMap&quot;">​</a></h1><p>XnneHangLab 项目的开发路线图与技术债务清理计划。（更新于 2026-07-08）</p><h2 id="记忆系统-llm-mode" tabindex="-1">记忆系统：LLM Mode <a class="header-anchor" href="#记忆系统-llm-mode" aria-label="Permalink to &quot;记忆系统：LLM Mode&quot;">​</a></h2><p><strong>状态：</strong> 设计完成（<a href="/adr/0001-llm-mode-memory.html">ADR-0001</a>），实施中 <strong>优先级：</strong> 高 <strong>设计文档：</strong> <a href="/adr/0001-llm-mode-memory.html">ADR-0001</a> | <a href="/adr/0002-memu-design-not-dependency.html">ADR-0002</a> | <a href="https://github.com/XnneHangLab/XnneHangLab/issues/471" target="_blank" rel="noreferrer">#471</a> / <a href="https://github.com/XnneHangLab/XnneHangLab/issues/468" target="_blank" rel="noreferrer">#468</a></p><p>用 categories + wiki-links + metadata 的扁平存储取代 Neo4j 语义节点（Domain / Topic / Scene / Predicate），结构节点（Agent / Character / User / Conversation）保留用于可视化。设计借鉴 memU（不引入其依赖，见 ADR-0002）。</p><p><strong>里程碑：</strong></p><table tabindex="0"><thead><tr><th>里程碑</th><th>内容</th><th>Issue</th><th>状态</th></tr></thead><tbody><tr><td>M1</td><td>存储层 — categories + metadata + 扁平条目</td><td><a href="https://github.com/XnneHangLab/XnneHangLab/issues/478" target="_blank" rel="noreferrer">#478</a></td><td>待开工</td></tr><tr><td>M2</td><td>检索 — wiki-link <code>[[category:item]]</code> 解析与关联抓取</td><td><a href="https://github.com/XnneHangLab/XnneHangLab/issues/479" target="_blank" rel="noreferrer">#479</a></td><td>待开工</td></tr><tr><td>M3</td><td>MemoryPlugin 接入 — 默认 LLM Mode，embedding 可选融合，mem0 迁移回退</td><td><a href="https://github.com/XnneHangLab/XnneHangLab/issues/480" target="_blank" rel="noreferrer">#480</a></td><td>待开工</td></tr><tr><td>M4</td><td>Neo4j 语义节点退役 — 实时管线停产语义节点</td><td><a href="https://github.com/XnneHangLab/XnneHangLab/issues/481" target="_blank" rel="noreferrer">#481</a></td><td>待开工</td></tr></tbody></table><p><strong>后续方向：</strong></p><ul><li>Multi-Character 记忆（<a href="https://github.com/XnneHangLab/XnneHangLab/issues/470" target="_blank" rel="noreferrer">#470</a> / <a href="https://github.com/XnneHangLab/XnneHangLab/issues/469" target="_blank" rel="noreferrer">#469</a>）— Agent 画像独立为 LLM Mode + User 模板继承</li><li>mem0 / Neo4j 基准线 — 退回 memory_bench 基准对照定位；embedding + graph traversal 作为研究线按基准数据立项（远期，非运行时并行模式）</li></ul><h2 id="tts-统一调度" tabindex="-1">TTS 统一调度 <a class="header-anchor" href="#tts-统一调度" aria-label="Permalink to &quot;TTS 统一调度&quot;">​</a></h2><p><strong>状态：</strong> 规划中 <strong>优先级：</strong> 中 <strong>关联：</strong> <a href="https://github.com/XnneHangLab/XnneHangLab/issues/402" target="_blank" rel="noreferrer">#402</a></p><p>统一 TTS 引擎（Genie-TTS / GSV-TTS-Lite / Qwen-TTS）的调度层，集中管理语音资源与情绪配置。</p><h2 id="插件与感知" tabindex="-1">插件与感知 <a class="header-anchor" href="#插件与感知" aria-label="Permalink to &quot;插件与感知&quot;">​</a></h2><ul><li><strong>AudioTriggerPlugin</strong>（<a href="https://github.com/XnneHangLab/XnneHangLab/issues/368" target="_blank" rel="noreferrer">#368</a>）— 预制音频库 + 大模型触发 + Live2D 联动</li><li><strong>异步 Screen Observation / Vision Input 插件架构</strong>（<a href="https://github.com/XnneHangLab/XnneHangLab/issues/380" target="_blank" rel="noreferrer">#380</a>）— 初版已由 <code>visual_observer</code> 插件落地（OCR 轮询 + 场景切换检测 + vision boost），作为 agent core 额外输入的通用架构化仍在设计</li><li><strong>统一 vision pipeline</strong>（<a href="https://github.com/XnneHangLab/XnneHangLab/issues/353" target="_blank" rel="noreferrer">#353</a>）— 将更多 tool callback image 接入统一视觉管线</li></ul><h2 id="功能开发" tabindex="-1">功能开发 <a class="header-anchor" href="#功能开发" aria-label="Permalink to &quot;功能开发&quot;">​</a></h2><h3 id="独立翻译大模型" tabindex="-1">独立翻译大模型 <a class="header-anchor" href="#独立翻译大模型" aria-label="Permalink to &quot;独立翻译大模型&quot;">​</a></h3><p><strong>状态：</strong> 规划中 <strong>优先级：</strong> 中</p><p>当前翻译依赖外部 DeepLX 服务与本地 GGUF 小模型（<code>/translate/llm</code>），计划评估更强的独立翻译模型。</p><p><strong>候选模型：</strong></p><ul><li><a href="https://modelscope.cn/models/Tencent-Hunyuan/HY-MT1.5-1.8B" target="_blank" rel="noreferrer">Tencent-Hunyuan/HY-MT1.5-1.8B</a> — 腾讯混元翻译模型</li></ul><p><strong>待完成：</strong></p><ul><li>[ ] 模型集成与推理封装</li><li>[ ] 路由层适配（保持 API 兼容）</li><li>[ ] 性能对比测试（vs DeepLX / Qwen2.5-0.5B）</li></ul><h2 id="技术债务" tabindex="-1">技术债务 <a class="header-anchor" href="#技术债务" aria-label="Permalink to &quot;技术债务&quot;">​</a></h2><h3 id="cli-模块定位" tabindex="-1">CLI 模块定位 <a class="header-anchor" href="#cli-模块定位" aria-label="Permalink to &quot;CLI 模块定位&quot;">​</a></h3><p><strong>状态：</strong> 待讨论 <strong>优先级：</strong> 低</p><p><code>cli.py</code> 当前只用于 ASR 命令行工具，是否保留需要评估。</p><p><strong>选项：</strong></p><ol><li>保留并扩展为完整的 CLI 工具集</li><li>移除，ASR 功能通过 API 调用</li><li>拆分到独立的 <code>lab-cli</code> 包</li></ol><h2 id="已完成-存档" tabindex="-1">已完成（存档） <a class="header-anchor" href="#已完成-存档" aria-label="Permalink to &quot;已完成（存档）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>说明</th></tr></thead><tbody><tr><td>工具系统重构：Tool / Skill / Plugin 三层架构</td><td><a href="https://github.com/XnneHangLab/XnneHangLab/issues/262" target="_blank" rel="noreferrer">#262</a> 设计已分阶段落地：内置 function calling、Plugin 注册 + ToolManager、Skill 文件系统、Hook 机制 + SystemPromptBuilder</td></tr><tr><td>memory_bench 定位调整</td><td>chat_router 已迁移至 <code>src/lab</code>（<a href="https://github.com/XnneHangLab/XnneHangLab/issues/274" target="_blank" rel="noreferrer">#274</a>），memory_bench 收敛为纯记忆后端（<code>/memory/search</code>、<code>/memory/add</code> + OpenAI 兼容代理）</td></tr></tbody></table><hr><p><em>本文档持续更新，反映项目最新规划。</em></p>',32)])])}const m=a(o,[["render",l]]);export{c as __pageData,m as default};
